/**
 * assignActionOutputs
 * -------------------
 * Type-only helper that assigns action output values in the action body,
 * enabling datapill references to step results.
 *
 * Rules
 * • `_outputs` is the output schema from `params.outputs` in the action body.
 * • `_values` keys are constrained to the declared output names — arbitrary
 *   keys produce a TypeScript error and Ctrl+Space shows valid output names.
 * • Each value must be assignable to the corresponding output type (string
 *   values are permitted for template expressions / datapills).
 *
 * This helper is erased at runtime – it only influences the TypeScript
 * type-checker.
 *
 * @param _outputs   Output schema from `params.outputs` in the action body.
 * @param _values    Partial record mapping output names to their values.
 */
export declare function AssignActionOutputs<O extends Record<string, unknown>>(_outputs: O, _values: {
    [K in keyof O]?: O[K] | string;
}): void;
